import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

const nr = { retried0: false, retried1: false };

test('happy path', async () => {
  const h = await create();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', ...nr });
  assert.equal((await h.start()).ok, true);
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.workDone('worker0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.equal(await h.worker('x'), null);
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', ...nr });
  await h.workDone('worker1');
  const msgs = await h.inFlight();
  assert.deepEqual(msgs[0].data, { task: 1, outcome: 'completed' });
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', ...nr });
});

test('failure while cancelling is recorded, no retry', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  assert.equal((await h.cancel()).ok, true);
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.filter((m) => m.action === 'Abort').length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', ...nr });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('cancel all', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', ...nr });
});

test('retry once then fail', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker1');
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: true, retried1: false });
});

test('timeout fails task, aborts worker, late report ignored', async () => {
  const h = await create();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.workDone('worker1');
  assert.equal((await h.taskTimeout(0)).ok, true);
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', ...nr });
  // worker0 finishes before the Abort arrives: its report is ignored
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', ...nr });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal((await h.taskTimeout(1)).ok, false);
});

test('timeout both while cancelling', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  await h.taskTimeout(1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'cancelled', task1: 'failed', ...nr });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('retry then succeed', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  await h.workDone('worker1');
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true });
});

